    for v in [1,0]:
        vals=[]
        for r in range(len(out)):
            for c in range(len(out[0])):
                if out[r][c]!=v: continue
                d=min(man((r,c),p) for p in pts)
                vals.append((int(d),r,c))
        vals.sort()
        print(' value',v,'dists',vals[:8],'...' ,len(vals))
for nm in [1,2,3]: analyze(nm)

import json
def f(inp):
    a=inp[0].index(2); n=len(inp[0])
    o=[[0]*n for _ in range(n)]
    for r in range((n+1)//2):
        o[r][a-r]=2; o[r][a+r]=2
    # diagonals d = 4-a + 4k, k>=0, paint r>=3, in bounds, non-V cells,
    # EXCEPT cells directly below the left-arm tip band (observed exclusion in demo1): r < 5 and c < a-2
    for k in range(0,25):
        d=4-a+4*k
        for r in range(3,n):
            c=r-d
            if 0<=c<n and o[r][c]!=2 and not (r<5 and c<a-2):
                o[r][c]=1
    return o
for nm in [1,2,3]:
    print(nm, f(G[f'Demo pair {nm} input'])==G[f'Demo pair {nm} output'])
